                var pp = m_accessor.GetPP(i);
                var upCount = m_accessor.GetWazaPPUpCount(i);
                m_accessor.SetWazaNo((byte)(i - 1), (uint)srcWazano);
                m_accessor.SetPP((byte)(i - 1), pp);
