		public void InheriteTamagoWaza(global::Pml.PokePara.CoreParam teacher) {
            if (GetMonsNo() != teacher.GetMonsNo())
                return;

            var eggWazaData = new EggWazaData();
            var personal = PersonalSystem.GetPersonalData(GetMonsNo(), GetFormNo());
            var eggMonsno = (MonsNo)personal.GetParam(ParamID.EGG_MONS_NO);
            var formParam = (personal.GetParam(ParamID.EGG_FORM_INHERIT_KAWARAZUNOISHI) != 0) ? ParamID.EGG_FORM_NO_KAWARAZUNOISHI : ParamID.EGG_FORM_NO;
            var eggFormno = (ushort)personal.GetParam(formParam);
            eggWazaData.Load(eggMonsno, eggFormno);

            for (byte i = 0; i < teacher.GetWazaCount(); i++)
            {
                var wazano = teacher.GetWazaNo(i);
                if (eggWazaData.IsContain(wazano))
                    AddWazaIfEmptyExist(wazano);
            }
        }
