            else if (m_accessor.GetWazaNo(2) == WazaNo.NULL)
                wazaIndex = 2;
            else if (m_accessor.GetWazaNo(3) == WazaNo.NULL)
                wazaIndex = 3;
            else
                return WazaLearningResult.FAILED_FULL;

            SetWaza(wazaIndex, wazano);
            return WazaLearningResult.SUCCEEDED;
        }
		public global::Pml.PokePara.WazaLearningResult LearnNewWazaOnCurrentLevel(ref uint sameLevelIndex, ref global::Pml.WazaNo newWazano, global::Pml.PokePara.CoreParam.WazaLearnWork work = null) {
            return LearnNewWazaOnLevel((byte)GetLevel(), ref sameLevelIndex, ref newWazano, work);
        }
		public global::Pml.PokePara.WazaLearningResult LearnNewWazaOnLevel(byte level, ref uint sameLevelIndex, ref global::Pml.WazaNo newWazano, global::Pml.PokePara.CoreParam.WazaLearnWork work = null) {
            PersonalSystem.LoadWazaOboeData(GetMonsNo(), GetFormNo());
            var num = PersonalSystem.GetWazaOboeNum();

            uint sameLevelCount = 0;
            for (ushort i = 0; i < num; i++)
            {
                var oboeLevel = PersonalSystem.GetWazaOboeLevel(i);
                var wazano = (WazaNo)PersonalSystem.GetWazaOboeWazaNo(i);
                if (PersonalSystem.GetWazaOboeKind(i) == OboeWazaKind.BASE)
                    continue;

                var isNotChecked = work == null || !work.IsCheckedWaza(wazano);

                if (level < oboeLevel)
                    return WazaLearningResult.FAILED_NOT_EXIST;

                if (level != oboeLevel)
                    continue;

                if (isNotChecked && sameLevelCount == sameLevelIndex)
                {
                    if (work != null)
                        work.AddCheckedWaza(wazano);

                    newWazano = wazano;
                    sameLevelIndex++;
                    return AddWazaIfEmptyExist(wazano);
                }

                sameLevelCount++;
            }

            return WazaLearningResult.FAILED_NOT_EXIST;
        }
		public global::Pml.PokePara.WazaLearningResult LearnNewWazaOnEvolution(ref uint learnIndex, ref global::Pml.WazaNo newWazano, global::Pml.PokePara.CoreParam.WazaLearnWork work = null) {
            PersonalSystem.LoadWazaOboeData(GetMonsNo(), GetFormNo());
            var num = PersonalSystem.GetWazaOboeNum();

            for (var i = learnIndex; i < num; i++)
            {
                var wazano = (WazaNo)PersonalSystem.GetWazaOboeWazaNo((ushort)i);
                if (PersonalSystem.GetWazaOboeKind((ushort)i) != OboeWazaKind.EVOLVE)
                    continue;

                if (work != null)
                {
                    if (work.IsCheckedWaza(wazano))
                        continue;

                    work.AddCheckedWaza(wazano);
                }

                newWazano = wazano;
                learnIndex = i + 1;
                return AddWazaIfEmptyExist(wazano);
            }

            return WazaLearningResult.FAILED_NOT_EXIST;
        }
		public global::System.Collections.Generic.HashSet<global::Pml.WazaNo> CollectRemindableWaza() {
            void CheckAndAddWazaNo(HashSet<WazaNo> list, WazaNo wazaNo)
            {
                if (wazaNo != WazaNo.NULL && !HaveWaza(wazaNo))
                    list.Add(wazaNo);
            }

            var wazaList = new HashSet<WazaNo>();

            CheckAndAddWazaNo(wazaList, m_accessor.GetTamagoWazaNo(0));
            CheckAndAddWazaNo(wazaList, m_accessor.GetTamagoWazaNo(1));
            CheckAndAddWazaNo(wazaList, m_accessor.GetTamagoWazaNo(2));
            CheckAndAddWazaNo(wazaList, m_accessor.GetTamagoWazaNo(3));

            for (int i = 0; i < 99; i++)
            {
                if (m_accessor.GetWazaRecordFlag((byte)i))
                    CheckAndAddWazaNo(wazaList, Pml.Item.ItemManager.Instance.GetWazaNo((ushort)(i + 1130)));
            }

            PersonalSystem.LoadWazaOboeData(GetMonsNo(), GetFormNo());
            var num = PersonalSystem.GetWazaOboeNum();

            for (ushort i = 0; i < num; i++)
            {
                if (PersonalSystem.GetWazaOboeKind(i) == OboeWazaKind.EVOLVE && GetLevel() >= PersonalSystem.GetWazaOboeLevel(i))
                    CheckAndAddWazaNo(wazaList, (WazaNo)PersonalSystem.GetWazaOboeWazaNo(i));
            }

            for (ushort i = 0; i < num; i++)
            {
                if (PersonalSystem.GetWazaOboeKind(i) == OboeWazaKind.BASE && GetLevel() >= PersonalSystem.GetWazaOboeLevel(i))
                    CheckAndAddWazaNo(wazaList, (WazaNo)PersonalSystem.GetWazaOboeWazaNo(i));
            }

            for (ushort i = 0; i < num; i++)
            {
                if (PersonalSystem.GetWazaOboeKind(i) == OboeWazaKind.LEVEL && GetLevel() >= PersonalSystem.GetWazaOboeLevel(i))
                    CheckAndAddWazaNo(wazaList, (WazaNo)PersonalSystem.GetWazaOboeWazaNo(i));
            }

            return wazaList;
        }
