		public void ChangeSex(global::Pml.Sex newSex) {
            if (GetSex() == newSex)
                return;

            var sexVector = GetSexVector();

            byte min;
            byte max;
            switch (newSex)
            {
                case Sex.MALE:
                    min = (byte)SexVector.ONLY_MALE;
                    max = (byte)SexVector.RANDOM_MALE_MAX;
                    break;
                case Sex.FEMALE:
                    min = (byte)SexVector.RANDOM_FEMALE_MIN;
                    max = (byte)SexVector.ONLY_FEMALE;
                    break;
                default:
                    min = (byte)SexVector.UNKNOWN;
                    max = (byte)SexVector.UNKNOWN;
                    break;
            }

            if (min <= sexVector && sexVector <= max)
                m_accessor.SetSex(newSex);
        }
