            m_accessor.SetTamagoFlag(true);
            m_accessor.SetNickName(PersonalSystem.GetMonsName(MonsNo.TAMAGO, (Dpr.Message.MessageEnumData.MsgLangId)GetLangId()));
            m_accessor.SetNickNameFlag(false);
            m_accessor.SetOriginalFriendship((byte)PersonalSystem.GetPersonalData(GetMonsNo(), GetFormNo()).GetParam(ParamID.EGG_BIRTH));
        }
