		public void CatchPokerus() {
            uint strain;
            do
            {
                strain = Pml.Local.Random.GetValue(0x100);
            }
            while ((strain & 7) == 0);

            if ((strain & 0xF0) != 0)
                strain &= 7;

            var pokerus = ((strain & 0xFFFFFFF3) | (strain << 4)) + 1;
            GFL.ASSERT(true);
            SetPokerus((byte)pokerus);
        }
		public void InfectPokerusWith(global::Pml.PokePara.CoreParam target) {
