        }
		public void DecreasePokerusDayCount(int passedDayCount) {
            var pokerus = GetPokerus();
            if ((pokerus & 0xFF) == 0)
                return;

            var strain = ((pokerus & 0xF0) != 0) ? (pokerus & 0xFFFFFFF0) : 0x10u;
            var dayCount = (int)(pokerus & 0xF);
            var newDayCount = (passedDayCount <= dayCount && passedDayCount < 5) ? (uint)(dayCount - passedDayCount) : 0u;
            var newPokerus = strain | newDayCount;

            GFL.ASSERT((newPokerus & 0xFF) != 0);
            SetPokerus((byte)newPokerus);
        }
