		public void RemoveAllRotomWaza() {
            for (byte wazaIndex = 0; wazaIndex < PmlConstants.MAX_WAZA_NUM; wazaIndex++)
            {
                var wazano = m_accessor.GetWazaNo(wazaIndex);

                for (ushort formno = 0; formno < 6; formno++)
                {
                    var rotomWazano = CalcTool.GetRotomuWazaNo(formno);
                    if (rotomWazano != WazaNo.NULL && wazano == rotomWazano)
                        RemoveWaza(wazaIndex);
                }
            }
        }
		public void SetRotomWaza(byte wazaIndex) {
            var formno = GetFormNo();
            var rotomWazano = CalcTool.GetRotomuWazaNo(formno);
            var wazaCount = GetWazaCount();

            if (formno == 0)
            {
                if (wazaCount == 0)
                    SetWaza(0, WazaNo.DENKISYOKKU);

                return;
            }

            if (wazaCount < PmlConstants.MAX_WAZA_NUM)
                PushWaza(rotomWazano);
            else
                SetWaza(wazaIndex, rotomWazano);
        }
		public global::Pml.PokePara.LoveLevel CheckLoveLevel(global::Pml.PokePara.CoreParam partner) {
            var eggGroup1 = new uint[2];
            PersonalSystem.LoadPersonalData(GetMonsNo(), GetFormNo());
            eggGroup1[0] = PersonalSystem.GetPersonalParam(ParamID.EGG_GROUP1);
            eggGroup1[1] = PersonalSystem.GetPersonalParam(ParamID.EGG_GROUP2);

            var eggGroup2 = new uint[2];
            PersonalSystem.LoadPersonalData(partner.GetMonsNo(), partner.GetFormNo());
            eggGroup2[0] = PersonalSystem.GetPersonalParam(ParamID.EGG_GROUP1);
            eggGroup2[1] = PersonalSystem.GetPersonalParam(ParamID.EGG_GROUP2);

            var monsno1 = GetMonsNo();
            var monsno2 = partner.GetMonsNo();
            var sex1 = GetSex();
            var sex2 = partner.GetSex();

            if (!CalcTool.CanCreateEgg(monsno1, sex1, eggGroup1[0], eggGroup1[1], monsno2, sex2, eggGroup2[0], eggGroup2[1]))
                return LoveLevel.WORST;

            return CalcTool.CalcLoveLevel(monsno1, GetID(), monsno2, partner.GetID());
        }
