		protected void UpdateCalcDatas(bool keepDead = true) {
            var isFastModeStarted = StartFastMode();

            UpdateLevel();
            UpdateMaxHpAndCorrectHp(keepDead);
            UpdateAtk();
            UpdateDef();
            UpdateSpAtk();
            UpdateSpDef();
            UpdateAgi();

            EndFastMode(isFastModeStarted);
        }
