		protected ushort CalcMaxHp_NotG() {
            var monsno = GetMonsNo();
            var level = (byte)GetLevel();
            var basic = GetBasicPower(PowerID.HP);
            var talent = GetTalentPower(PowerID.HP);
            var effort = GetEffortPower(PowerID.HP);
            return CalcTool.CalcMaxHp(monsno, level, (ushort)basic, (ushort)talent, (ushort)effort);
        }
